// Types for the batch-4 heavy-duty data files. The .ts data files in this folder
// are generated by scripts/extract-hd.mjs from the maker PDFs; this type only has
// to accept that generated shape. Fields are a union across the three makers
// (kind: 'ford-conv' | 'gm' | 'ram'); unused ones stay undefined per kind.
import type { SourceId } from '../../sources';

export type HdKind = 'ford-conv' | 'gm' | 'ram';

export interface HdRow {
  // the generated files carry a few extra provenance fields (table, raw, etc.)
  [key: string]: unknown;
  id: string;
  page?: string;
  pageNum?: number;
  engine: string;
  axle?: string;
  gcwr?: number;
  gvwr?: number | null;
  // Ford conventional
  cab?: string;
  drive?: string;
  wheelbase?: string;
  box?: string;
  model?: string | null;
  rearWheels?: string;
  hitch?: string;
  maxTrailer?: number;
  maxTrailerAlt?: number | null;
  gcwrFoot?: string[];
  // GM
  panel?: string;
  wheel?: string;
  conv?: number | null;
  gnRaw?: string;
  gn?: number | null;
  gnAlt?: number | null;
  gnFoot?: string[];
  // Ram
  group?: string;
  cabLabel?: string;
  bed?: string;
  wheels?: string;
  note?: string;
  // shared
  footnotes?: string[];
  raw?: string;
  colLabel?: string;
  rowLabel?: string;
}

export interface MaxEntry {
  value: number;
  config: string;
}
export interface MaxByEngine {
  engine: string;
  conventional?: MaxEntry | null;
  gooseneck?: MaxEntry | null;
  trailer?: MaxEntry | null;
}

export interface HitchRow {
  model: string;
  maxTrailer: number;
  maxTongue: number;
}

export interface PayloadRow {
  group?: string;
  cab: string;
  bed: string;
  engine: string;
  gvwr: number;
  drive: string;
  payload: number;
  colLabel?: string;
}

export interface HdFootnote {
  marker: string;
  page?: number;
  text: string;
}

export interface HdVehicle {
  slug: string;
  make: string;
  model: string;
  year: number;
  kind: HdKind;
  verified: boolean;
  source: SourceId;
  sourceName: string;
  readDate: string;
  pages: string;
  rows: HdRow[];
  maxByEngine: MaxByEngine[];
  hitchTable?: HitchRow[];
  payloadRows?: PayloadRow[];
  notes: string[];
  fordFifthPending?: string;
  footnotes: HdFootnote[];
}
